CREATE TABLE IF NOT EXISTS admin_nonces(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY,name TEXT NOT NULL,target_ip TEXT NOT NULL UNIQUE,vpn_port INTEGER NOT NULL DEFAULT 443,state TEXT NOT NULL DEFAULT 'installing',revision INTEGER NOT NULL DEFAULT 0,acked_revision INTEGER NOT NULL DEFAULT 0,last_seen INTEGER NOT NULL DEFAULT 0,healthy INTEGER NOT NULL DEFAULT 0,token_hash TEXT,policy_key TEXT,public_key TEXT,short_id TEXT,sni TEXT,policy_payload TEXT);
CREATE TABLE IF NOT EXISTS installation_jobs(id TEXT PRIMARY KEY,node_id TEXT,kind TEXT NOT NULL,user_id TEXT NOT NULL,target_ip TEXT NOT NULL,port INTEGER NOT NULL,username TEXT NOT NULL DEFAULT '',fingerprint TEXT,encrypted_credentials TEXT,credentials_expire_at INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'queued',lease_id TEXT,lease_until INTEGER NOT NULL DEFAULT 0,runner_id TEXT,safe_code TEXT,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,artifact_version TEXT NOT NULL DEFAULT '26.3.27');
CREATE UNIQUE INDEX IF NOT EXISTS active_target_job ON installation_jobs(target_ip) WHERE state NOT IN ('ready','failed');
